/**
 * Encryption for the keys a visitor saves in the browser edition.
 *
 * Secrets are stored in localStorage only as enc:v1:<iv · ciphertext>,
 * sealed with AES-256-GCM (the setting's name bound in, so a value can't be
 * moved to another setting or altered unnoticed). The key is generated by
 * the browser as NON-EXTRACTABLE and kept in IndexedDB: the page can ask the
 * browser to use it, but no script, not even Divina's own, can ever read
 * its bytes out. A copy of the browser's storage files is useless without
 * this browser profile's key store.
 *
 * What this can't stop: someone using this browser profile on your unlocked
 * computer, or a malicious browser extension you've allowed to run on the
 * site. The page's strict Content-Security-Policy stops other sites' scripts.
 */
export const SEALED = 'enc:v1:';
const DB = 'divina-vault';
const STORE = 'keys';
const ID = 'settings-v1';

function idb<T>(mode: IDBTransactionMode, op: (s: IDBObjectStore) => IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    const open = indexedDB.open(DB, 1);
    open.onupgradeneeded = () => open.result.createObjectStore(STORE);
    open.onerror = () => reject(open.error);
    open.onsuccess = () => {
      const db = open.result;
      const req = op(db.transaction(STORE, mode).objectStore(STORE));
      req.onsuccess = () => {
        resolve(req.result);
        db.close();
      };
      req.onerror = () => {
        reject(req.error);
        db.close();
      };
    };
  });
}

let keyP: Promise<CryptoKey | null> | null = null;

/** This browser's key, created on first use. Null where the browser can't keep one. */
function vaultKey(): Promise<CryptoKey | null> {
  return (keyP ??= (async () => {
    try {
      const have = await idb<CryptoKey | undefined>('readonly', (s) => s.get(ID));
      if (have) return have;
      const k = await crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
      await idb('readwrite', (s) => s.put(k, ID));
      return k;
    } catch {
      return null;
    }
  })());
}

const b64 = (b: Uint8Array) => btoa(String.fromCharCode(...b));
const unb64 = (s: string) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));

export const isSealed = (v: string) => v.startsWith(SEALED);

/** The sealed value, or null if this browser can't keep a key (then nothing is saved). */
export async function seal(name: string, plain: string): Promise<string | null> {
  const key = await vaultKey();
  if (!key) return null;
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv, additionalData: new TextEncoder().encode(name) }, key, new TextEncoder().encode(plain)));
  const out = new Uint8Array(iv.length + ct.length);
  out.set(iv);
  out.set(ct, iv.length);
  return SEALED + b64(out);
}

/** The secret, or undefined if it can't be opened in this browser or was altered. */
export async function unseal(name: string, sealed: string): Promise<string | undefined> {
  if (!isSealed(sealed)) return undefined;
  const key = await vaultKey();
  if (!key) return undefined;
  try {
    const raw = unb64(sealed.slice(SEALED.length));
    const pt = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: raw.subarray(0, 12), additionalData: new TextEncoder().encode(name) }, key, raw.subarray(12));
    return new TextDecoder().decode(pt);
  } catch {
    return undefined;
  }
}
